fn scroll_by_page_amount_from_f64(amount: f64) -> Option<WindowScrollByPageAmount> {
    amount
        .is_finite()
        .then_some(WindowScrollByPageAmount::from_per_mille(
            (amount * f64::from(WINDOW_SCROLL_PAGE_AMOUNT_SCALE)).round() as i32,
        ))
}

