fn spawn_command_query_from_prefix(query: &str, prefix: &str) -> Option<WindowSpawnCommandQuery> {
    let command = strip_query_prefix_from_any(query, &[prefix])?;
    if command.trim_start().starts_with('{') {
        return None;
    }
    let words = command_palette_query_words(command)?;
    let mut words = words.iter().map(String::as_str).peekable();
    let mut options = parse_spawn_command_query_options(&mut words).ok()?;
    loop {
        if let Some(value) = words
            .peek()
            .and_then(|word| query_text_assignment_value_from_token(word, &["cwd"]))
        {
            options.cwd = Some(non_empty_spawn_command_option_value(value).ok()?);
            words.next();
            continue;
        }
        if let Some(value) = words.peek().and_then(|word| {
            query_text_assignment_value_from_token(
                word,
                &["set_environment_variables", "set-environment-variables"],
            )
        }) {
            let (name, value) = spawn_command_environment_from_query(value).ok()?;
            options.environment.insert(name, value);
            words.next();
            continue;
        }
        if let Some(value) = words
            .peek()
            .and_then(|word| query_text_assignment_value_from_token(word, &["domain"]))
        {
            options.domain = Some(spawn_command_domain_from_query(value)?);
            words.next();
            continue;
        }
        if let Some(value) = words
            .peek()
            .and_then(|word| query_text_assignment_value_from_token(word, &["position"]))
        {
            options.window_position = Some(spawn_command_window_position_from_query(value).ok()?);
            words.next();
            continue;
        }
        break;
    }
    let program = words.next()?;
    let program = query_assignment_value_from_token(program, &["args"])
        .unwrap_or(program)
        .to_owned();
    let args = words.map(str::to_owned).collect::<Vec<_>>();

    Some(WindowSpawnCommandQuery {
        label: None,
        program,
        args,
        cwd: options.cwd,
        environment: options.environment,
        domain: options.domain,
        window_position: options.window_position,
    })
}

fn command_palette_query_words(query: &str) -> Option<Vec<String>> {
    command_palette_query_word_spans(query)
        .map(|words| words.into_iter().map(|(word, _, _)| word).collect())
}

fn command_palette_query_word_spans(query: &str) -> Option<Vec<(String, usize, usize)>> {
    let mut words = Vec::new();
    let mut word = String::new();
    let mut quote = None;
    let mut escaped = false;
    let mut in_word = false;
    let mut word_start = 0;

    for (index, character) in query.char_indices() {
        if escaped {
            word.push(character);
            escaped = false;
            in_word = true;
            continue;
        }

        match quote {
            Some(_) if character == '\\' => {
                escaped = true;
                in_word = true;
            }
            Some(active_quote) if character == active_quote => {
                quote = None;
                in_word = true;
            }
            None if character == '"' || character == '\'' => {
                if !in_word {
                    word_start = index;
                }
                quote = Some(character);
                in_word = true;
            }
            None if character.is_whitespace() => {
                if in_word {
                    words.push((std::mem::take(&mut word), word_start, index));
                    in_word = false;
                }
            }
            Some(_) | None => {
                if !in_word {
                    word_start = index;
                }
                word.push(character);
                in_word = true;
            }
        }
    }

    if quote.is_some() {
        return None;
    }

    if escaped {
        word.push('\\');
    }

    if in_word {
        words.push((word, word_start, query.len()));
    }

    Some(words)
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct WindowSpawnCommandQueryOptions {
    cwd: Option<String>,
    environment: BTreeMap<String, String>,
    domain: Option<WindowSpawnTabDomain>,
    window_position: Option<WindowPosition>,
}

impl WindowSpawnCommandQueryOptions {
    #[expect(
        clippy::unused_self,
        reason = "method shape is retained for compatibility call-site consistency"
    )]
    fn launch_menu_label(&self) -> String {
        "New Tab".to_owned()
    }
}

fn parse_spawn_command_query_options<'a, I>(
    words: &mut std::iter::Peekable<I>,
) -> Result<WindowSpawnCommandQueryOptions, ()>
where
    I: Iterator<Item = &'a str>,
{
    let mut options = WindowSpawnCommandQueryOptions::default();
    while parse_spawn_command_query_option(words, &mut options)? {}
    Ok(options)
}

#[expect(
    clippy::too_many_lines,
    reason = "compatibility reducer remains linear to preserve evaluation and precedence order"
)]
fn parse_spawn_command_query_option<'a, I>(
    words: &mut std::iter::Peekable<I>,
    options: &mut WindowSpawnCommandQueryOptions,
) -> Result<bool, ()>
where
    I: Iterator<Item = &'a str>,
{
    match words.peek().copied() {
        Some(option) if option.eq_ignore_ascii_case("--domain") => {
            words.next();
            let value = words.next().ok_or(())?;
            options.domain = Some(spawn_command_domain_from_query(value).ok_or(())?);
            Ok(true)
        }
        Some(option) if starts_with_ascii_case_insensitive(option, "--domain=") => {
            let value = strip_query_prefix_from_any(option, &["--domain="]).ok_or(())?;
            words.next();
            options.domain = Some(spawn_command_domain_from_query(value).ok_or(())?);
            Ok(true)
        }
        Some(option) if option.eq_ignore_ascii_case("--cwd") => {
            words.next();
            let value = words.next().ok_or(())?;
            options.cwd = Some(non_empty_spawn_command_option_value(value)?);
            Ok(true)
        }
        Some(option) if starts_with_ascii_case_insensitive(option, "--cwd=") => {
            let value = strip_query_prefix_from_any(option, &["--cwd="]).ok_or(())?;
            words.next();
            options.cwd = Some(non_empty_spawn_command_option_value(value)?);
            Ok(true)
        }
        Some(option) if option.eq_ignore_ascii_case("--env") => {
            words.next();
            let value = words.next().ok_or(())?;
            let (name, value) = spawn_command_environment_from_query(value)?;
            options.environment.insert(name, value);
            Ok(true)
        }
        Some(option) if starts_with_ascii_case_insensitive(option, "--env=") => {
            let value = strip_query_prefix_from_any(option, &["--env="]).ok_or(())?;
            words.next();
            let (name, value) = spawn_command_environment_from_query(value)?;
            options.environment.insert(name, value);
            Ok(true)
        }
        Some(option)
            if option.eq_ignore_ascii_case("--set-environment-variables")
                || option.eq_ignore_ascii_case("--set_environment_variables") =>
        {
            words.next();
            let value = words.next().ok_or(())?;
            let (name, value) = spawn_command_environment_from_query(value)?;
            options.environment.insert(name, value);
            Ok(true)
        }
        Some(option)
            if starts_with_ascii_case_insensitive(option, "--set-environment-variables=")
                || starts_with_ascii_case_insensitive(option, "--set_environment_variables=") =>
        {
            let value = strip_query_prefix_from_any(
                option,
                &[
                    "--set-environment-variables=",
                    "--set_environment_variables=",
                ],
            )
            .ok_or(())?;
            words.next();
            let (name, value) = spawn_command_environment_from_query(value)?;
            options.environment.insert(name, value);
            Ok(true)
        }
        Some(option) if option.eq_ignore_ascii_case("--position") => {
            words.next();
            let value = words.next().ok_or(())?;
            options.window_position = Some(spawn_command_window_position_from_query(value)?);
            Ok(true)
        }
        Some(option) if starts_with_ascii_case_insensitive(option, "--position=") => {
            let value = strip_query_prefix_from_any(option, &["--position="]).ok_or(())?;
            words.next();
            options.window_position = Some(spawn_command_window_position_from_query(value)?);
            Ok(true)
        }
        Some(option) => {
            if let Some(value) = query_text_assignment_value_from_token(option, &["cwd"]) {
                words.next();
                options.cwd = Some(non_empty_spawn_command_option_value(value)?);
                return Ok(true);
            }
            if let Some(value) = query_text_assignment_value_from_token(option, &["domain"]) {
                words.next();
                options.domain = Some(spawn_command_domain_from_query(value).ok_or(())?);
                return Ok(true);
            }
            if let Some(value) = query_text_assignment_value_from_token(
                option,
                &["set_environment_variables", "set-environment-variables"],
            ) {
                words.next();
                let (name, value) = spawn_command_environment_from_query(value)?;
                options.environment.insert(name, value);
                return Ok(true);
            }
            if let Some(value) = query_text_assignment_value_from_token(option, &["position"]) {
                words.next();
                options.window_position = Some(spawn_command_window_position_from_query(value)?);
                return Ok(true);
            }
            Ok(false)
        }
        None => Ok(false),
    }
}

fn spawn_command_domain_from_query(domain: &str) -> Option<WindowSpawnTabDomain> {
    let domain = domain.trim();
    if domain.is_empty() {
        return None;
    }
    if domain.starts_with('{') {
        return spawn_tab_domain_lua_table_from_query(domain);
    }
    let normalized = domain
        .chars()
        .filter(|character| !character.is_whitespace() && *character != '-' && *character != '_')
        .collect::<String>()
        .to_ascii_lowercase();
    match normalized.as_str() {
        "currentpanedomain" | "currentpane" | "current" => {
            Some(WindowSpawnTabDomain::CurrentPaneDomain)
        }
        "defaultdomain" | "default" => Some(WindowSpawnTabDomain::DefaultDomain),
        _ => Some(WindowSpawnTabDomain::DomainName(domain.to_owned())),
    }
}

fn native_spawn_domain_config_text(domain: &WindowSpawnTabDomain) -> String {
    match domain {
        WindowSpawnTabDomain::CurrentPaneDomain => "CurrentPaneDomain".to_owned(),
        WindowSpawnTabDomain::DefaultDomain => "DefaultDomain".to_owned(),
        WindowSpawnTabDomain::DomainName(name) => name.clone(),
        WindowSpawnTabDomain::DomainId(id) => format!("DomainId:{id}"),
    }
}

fn attach_domain_from_query(query: &str) -> Option<String> {
    attach_domain_from_query_with_static_source(None, query)
}

fn attach_domain_from_query_with_static_source(
    static_source: Option<LuaStaticSource<'_>>,
    query: &str,
) -> Option<String> {
    let indexed_query;
    let query = if let Some(query) = strip_wezterm_action_prefix(query) {
        query
    } else if let Some(query) = strip_wezterm_action_index_prefix(query) {
        indexed_query = query;
        indexed_query.as_str()
    } else {
        query
    };

    if let Some(domain) = strip_lua_function_call_from_query(query, "attachdomain") {
        if (domain.trim_start().starts_with('{') || static_source.is_some())
            && let Some(domain) =
                attach_domain_lua_table_from_query_with_static_source(static_source, domain)
        {
            return Some(domain);
        }
        return named_domain_from_query_with_static_source(static_source, domain);
    }

    if let Some(domain) = strip_query_table_assignment_from_prefix(query, "attachdomain=")
        && (domain.trim_start().starts_with('{') || static_source.is_some())
    {
        return attach_domain_lua_table_from_query_with_static_source(static_source, domain);
    }

    let domain = strip_query_prefix_from_any(
        query,
        &[
            "attach domain=",
            "attach domain ",
            "attachdomain=",
            "attachdomain ",
        ],
    )?;
    if domain.trim_start().starts_with('{') {
        return attach_domain_lua_table_from_query_with_static_source(static_source, domain);
    }
    named_domain_from_query_with_static_source(static_source, domain)
}

fn attach_domain_lua_table_from_query_with_static_source(
    static_source: Option<LuaStaticSource<'_>>,
    value: &str,
) -> Option<String> {
    let value = value.trim();
    let resolved_value;
    let value = if value.starts_with('{') {
        value
    } else {
        let static_source = static_source?;
        resolved_value = lua_table_insert_value_table_string_from_query(
            static_source.source,
            value,
            static_source.max_start,
        )?;
        resolved_value.as_str()
    };
    let table = value.strip_prefix('{')?.strip_suffix('}')?.trim();
    let mut domain_name = None;
    let mut domain_id = None;
    for field in split_lua_table_top_level_fields(table)? {
        let field = field.trim();
        if field.is_empty() {
            continue;
        }
        let (key, value) = split_lua_table_assignment_from_field(field)?;
        let key = split_lua_table_key_from_query_with_static_source(static_source, key.trim())?;
        if domain_name.is_some() || domain_id.is_some() {
            return None;
        }
        if key.eq_ignore_ascii_case("domainname") {
            let value = parse_maybe_static_query_text(static_source, value)?;
            if value.is_empty() {
                return None;
            }
            domain_name = Some(value);
        } else if key.eq_ignore_ascii_case("domainid") {
            domain_id = Some(parse_maybe_static_usize_query(static_source, value)?);
        } else {
            return None;
        }
    }
    if let Some(domain_name) = domain_name {
        return Some(domain_name);
    }
    domain_id.map(|domain_id| format!("domainid:{domain_id}"))
}

fn detach_domain_from_query(query: &str) -> Option<WindowDomainSelector> {
    detach_domain_from_query_with_static_source(None, query)
}

fn detach_domain_from_query_with_static_source(
    static_source: Option<LuaStaticSource<'_>>,
    query: &str,
) -> Option<WindowDomainSelector> {
    let indexed_query;
    let query = if let Some(query) = strip_wezterm_action_prefix(query) {
        query
    } else if let Some(query) = strip_wezterm_action_index_prefix(query) {
        indexed_query = query;
        indexed_query.as_str()
    } else {
        query
    };

    if let Some(domain) = strip_lua_function_call_from_query(query, "detachdomain") {
        if (domain.trim_start().starts_with('{') || static_source.is_some())
            && let Some(selector) = window_domain_selector_lua_table_from_query_with_static_source(
                static_source,
                domain,
            )
        {
            return Some(selector);
        }
        return window_domain_selector_from_query_with_static_source(static_source, domain);
    }

    if let Some(domain) = strip_query_table_assignment_from_prefix(query, "detachdomain=")
        && (domain.trim_start().starts_with('{') || static_source.is_some())
        && let Some(selector) =
            window_domain_selector_lua_table_from_query_with_static_source(static_source, domain)
    {
        return Some(selector);
    }

    let domain = strip_query_prefix_from_any(
        query,
        &[
            "detach domain=",
            "detach domain ",
            "detachdomain=",
            "detachdomain ",
        ],
    )?;
    if domain.trim_start().starts_with('{') {
        return window_domain_selector_lua_table_from_query_with_static_source(
            static_source,
            domain,
        );
    }
    window_domain_selector_from_query_with_static_source(static_source, domain)
}

fn named_domain_from_query_with_static_source(
    static_source: Option<LuaStaticSource<'_>>,
    domain: &str,
) -> Option<String> {
    let domain = strip_query_prefix_from_any(
        domain,
        &[
            "domain name=",
            "domain name ",
            "domain=",
            "domain ",
            "name=",
            "name ",
        ],
    )
    .unwrap_or(domain);
    parse_maybe_static_query_text(static_source, domain).filter(|domain| !domain.is_empty())
}

fn window_domain_selector_from_query_with_static_source(
    static_source: Option<LuaStaticSource<'_>>,
    domain: &str,
) -> Option<WindowDomainSelector> {
    let domain = named_domain_from_query_with_static_source(static_source, domain)?;
    let normalized = domain
        .chars()
        .filter(|character| !character.is_whitespace() && *character != '-' && *character != '_')
        .collect::<String>()
        .to_ascii_lowercase();
    match normalized.as_str() {
        "currentpanedomain" | "currentpane" | "current" => {
            Some(WindowDomainSelector::CurrentPaneDomain)
        }
        "defaultdomain" | "default" => Some(WindowDomainSelector::DefaultDomain),
        _ => Some(WindowDomainSelector::DomainName(domain)),
    }
}

fn window_domain_selector_lua_table_from_query_with_static_source(
    static_source: Option<LuaStaticSource<'_>>,
    value: &str,
) -> Option<WindowDomainSelector> {
    let value = value.trim();
    let resolved_value;
    let value = if value.starts_with('{') {
        value
    } else {
        let static_source = static_source?;
        resolved_value = lua_table_insert_value_table_string_from_query(
            static_source.source,
            value,
            static_source.max_start,
        )?;
        resolved_value.as_str()
    };
    let table = value.trim().strip_prefix('{')?.strip_suffix('}')?.trim();
    let mut domain = None;
    for field in split_lua_table_top_level_fields(table)? {
        let field = field.trim();
        if field.is_empty() {
            continue;
        }
        let (key, value) = split_lua_table_assignment_from_field(field)?;
        let key = split_lua_table_key_from_query_with_static_source(static_source, key.trim())?;
        if domain.is_some() {
            return None;
        }
        if key.eq_ignore_ascii_case("domainname") {
            let value = parse_maybe_static_query_text(static_source, value)?;
            if value.is_empty() {
                return None;
            }
            domain = Some(WindowDomainSelector::DomainName(value));
        } else if key.eq_ignore_ascii_case("domainid") {
            domain = Some(WindowDomainSelector::DomainId(
                parse_maybe_static_usize_query(static_source, value)?,
            ));
        } else {
            return None;
        }
    }
    domain
}

fn spawn_command_environment_from_query(environment: &str) -> Result<(String, String), ()> {
    let (name, value) = environment.split_once('=').ok_or(())?;
    let name = non_empty_spawn_command_option_value(name)?;
    Ok((name, value.to_owned()))
}

fn non_empty_spawn_command_option_value(value: &str) -> Result<String, ()> {
    if value.is_empty() {
        Err(())
    } else {
        Ok(value.to_owned())
    }
}

fn spawn_command_window_position_from_query(position: &str) -> Result<WindowPosition, ()> {
    let (origin, coordinates) =
        if let Some(coordinates) = strip_query_prefix_from_any(position, &["screen:"]) {
            (WindowPositionOrigin::Screen, coordinates)
        } else if let Some(coordinates) = strip_query_prefix_from_any(position, &["main:"]) {
            (WindowPositionOrigin::Main, coordinates)
        } else if let Some(coordinates) = strip_query_prefix_from_any(position, &["active:"]) {
            (WindowPositionOrigin::Active, coordinates)
        } else if let Some((monitor, coordinates)) = position.split_once(':') {
            if monitor.is_empty() {
                return Err(());
            }
            (
                WindowPositionOrigin::Monitor(monitor.to_owned()),
                coordinates,
            )
        } else {
            (WindowPositionOrigin::Screen, position)
        };

    if coordinates.contains(':') {
        return Err(());
    }
    let (x, y) = coordinates.split_once(',').ok_or(())?;
    if y.contains(',') {
        return Err(());
    }
    let x = x.parse::<i32>().map_err(|_| ())?;
    let y = y.parse::<i32>().map_err(|_| ())?;
    Ok(WindowPosition { origin, x, y })
}

fn spawn_command_window_position_value_from_query_with_static_source(
    static_source: Option<LuaStaticSource<'_>>,
    position: &str,
) -> Result<WindowPosition, ()> {
    let position = position.trim();
    if position.starts_with('{') {
        return spawn_command_window_position_table_from_query(position);
    }
    let position = parse_maybe_static_query_text(static_source, position).ok_or(())?;
    spawn_command_window_position_from_query(&position)
}

fn spawn_command_window_position_table_from_query(position: &str) -> Result<WindowPosition, ()> {
    let table = position
        .trim()
        .strip_prefix('{')
        .and_then(|table| table.strip_suffix('}'))
        .ok_or(())?
        .trim();
    let mut x = None;
    let mut y = None;
    let mut origin = None;
    for field in split_lua_table_top_level_fields(table).ok_or(())? {
        let field = field.trim();
        if field.is_empty() {
            continue;
        }
        let (key, value) = split_lua_table_assignment_from_field(field).ok_or(())?;
        let key = split_lua_table_key_from_query(key.trim()).ok_or(())?;
        let value = value.trim();
        if key.eq_ignore_ascii_case("x") {
            if x.is_some() {
                return Err(());
            }
            x = Some(spawn_command_window_position_coordinate_from_query(value)?);
        } else if key.eq_ignore_ascii_case("y") {
            if y.is_some() {
                return Err(());
            }
            y = Some(spawn_command_window_position_coordinate_from_query(value)?);
        } else if key.eq_ignore_ascii_case("origin") {
            if origin.is_some() {
                return Err(());
            }
            origin = Some(spawn_command_window_position_origin_from_query(value)?);
        } else {
            return Err(());
        }
    }
    Ok(WindowPosition {
        origin: origin.unwrap_or(WindowPositionOrigin::Screen),
        x: x.ok_or(())?,
        y: y.ok_or(())?,
    })
}

fn spawn_command_window_position_coordinate_from_query(value: &str) -> Result<i32, ()> {
    let value = parse_maybe_quoted_query_text(value).ok_or(())?;
    value.parse().map_err(|_| ())
}

fn spawn_command_window_position_origin_from_query(
    value: &str,
) -> Result<WindowPositionOrigin, ()> {
    let value = value.trim();
    if value.starts_with('{') {
        let table = value
            .strip_prefix('{')
            .and_then(|table| table.strip_suffix('}'))
            .ok_or(())?
            .trim();
        let mut monitor = None;
        for field in split_lua_table_top_level_fields(table).ok_or(())? {
            let field = field.trim();
            if field.is_empty() {
                continue;
            }
            let (key, value) = split_lua_table_assignment_from_field(field).ok_or(())?;
            let key = split_lua_table_key_from_query(key.trim()).ok_or(())?;
            if !key.eq_ignore_ascii_case("named") || monitor.is_some() {
                return Err(());
            }
            let value = parse_maybe_quoted_query_text(value.trim()).ok_or(())?;
            monitor = Some(non_empty_spawn_command_option_value(&value)?);
        }
        return monitor.map(WindowPositionOrigin::Monitor).ok_or(());
    }

    let value = parse_maybe_quoted_query_text(value).ok_or(())?;
    let normalized = value
        .chars()
        .filter(|character| !character.is_whitespace() && *character != '-' && *character != '_')
        .collect::<String>()
        .to_ascii_lowercase();
    match normalized.as_str() {
        "screencoordinatesystem" | "screen" => Ok(WindowPositionOrigin::Screen),
        "mainscreen" | "main" => Ok(WindowPositionOrigin::Main),
        "activescreen" | "active" => Ok(WindowPositionOrigin::Active),
        _ => Err(()),
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum WindowSearchCommandQuery {
    Pattern {
        pattern: String,
        match_type: WindowSearchMatchType,
    },
    #[allow(dead_code)]
    CurrentSelectionOrEmptyString,
}

fn search_query_from_query(query: &str) -> Option<WindowSearchCommandQuery> {
    search_query_from_query_with_static_source(None, query)
}

fn search_query_from_query_with_static_source(
    static_source: Option<LuaStaticSource<'_>>,
    query: &str,
) -> Option<WindowSearchCommandQuery> {
    let indexed_query;
    let query = if let Some(query) = strip_wezterm_action_prefix(query) {
        query
    } else if let Some(query) = strip_wezterm_action_index_prefix(query) {
        indexed_query = query;
        indexed_query.as_str()
    } else {
        query
    };

    if let Some(search_query) =
        search_query_lua_action_from_query_with_static_source(static_source, query)
    {
        return Some(search_query);
    }

    let pattern = strip_query_prefix_from_any(query, &["search=", "search "])?;
    if pattern.is_empty() {
        return None;
    }
    if !(pattern.starts_with('"') || pattern.starts_with('\''))
        && search_current_selection_query_matches(pattern)
    {
        return Some(WindowSearchCommandQuery::CurrentSelectionOrEmptyString);
    }

    let (pattern, match_type) =
        if let Some(pattern) = search_query_strip_match_type_prefix(pattern, &["regex"]) {
            (pattern, WindowSearchMatchType::Regex)
        } else if let Some(pattern) = search_query_strip_match_type_prefix(
            pattern,
            &[
                "case-sensitive",
                "case sensitive",
                "case sensitive string",
                "casesensitivestring",
            ],
        ) {
            (pattern, WindowSearchMatchType::CaseSensitive)
        } else if let Some(pattern) = search_query_strip_match_type_prefix(
            pattern,
            &[
                "case-insensitive",
                "case insensitive",
                "case in sensitive",
                "case insensitive string",
                "case in sensitive string",
                "caseinsensitivestring",
            ],
        ) {
            (pattern, WindowSearchMatchType::CaseInsensitive)
        } else {
            (pattern, WindowSearchMatchType::CaseSensitive)
        };

    let pattern = parse_maybe_static_query_text(static_source, pattern)?;
    Some(WindowSearchCommandQuery::Pattern {
        pattern,
        match_type,
    })
}

fn search_query_lua_action_from_query_with_static_source(
    static_source: Option<LuaStaticSource<'_>>,
    query: &str,
) -> Option<WindowSearchCommandQuery> {
    if let Some(value) = strip_lua_function_call_from_query(query, "search") {
        let value = value.trim();
        if value.starts_with('{') {
            return search_query_lua_table_from_query_with_static_source(static_source, value);
        }
        if static_source.is_some()
            && let Some(search_query) =
                search_query_lua_table_from_query_with_static_source(static_source, value)
        {
            return Some(search_query);
        }
        let value = parse_maybe_static_query_text(static_source, value)?;
        return search_query_lua_string_from_value(&value);
    }

    if let Some(value) = strip_query_prefix_from_any(query, &["search "]) {
        if value.trim_start().starts_with('{') {
            return search_query_lua_table_from_query_with_static_source(static_source, value);
        }
        let value = parse_maybe_static_query_text(static_source, value)?;
        if let Some(search_query) = search_query_lua_string_from_value(&value) {
            return Some(search_query);
        }
    }

    if let Some(value) = strip_query_table_assignment_from_prefix(query, "search=")
        && value.trim_start().starts_with('{')
    {
        return search_query_lua_table_from_query_with_static_source(static_source, value);
    }

    None
}

fn search_query_lua_string_from_value(value: &str) -> Option<WindowSearchCommandQuery> {
    search_current_selection_query_matches(value)
        .then_some(WindowSearchCommandQuery::CurrentSelectionOrEmptyString)
}

fn search_query_lua_table_from_query_with_static_source(
    static_source: Option<LuaStaticSource<'_>>,
    value: &str,
) -> Option<WindowSearchCommandQuery> {
    let value = value.trim();
    let resolved_value;
    let value = if value.starts_with('{') {
        value
    } else {
        let static_source = static_source?;
        resolved_value = lua_table_insert_value_table_string_from_query(
            static_source.source,
            value,
            static_source.max_start,
        )?;
        resolved_value.as_str()
    };
    let table = value.trim().strip_prefix('{')?.strip_suffix('}')?.trim();
    let mut search_query = None;

    for field in split_lua_table_top_level_fields(table)? {
        let field = field.trim();
        if field.is_empty() {
            continue;
        }
        let (name, value) = split_lua_table_assignment_from_field(field)?;
        let name = split_lua_table_key_from_query_with_static_source(static_source, name.trim())?;
        let value = parse_maybe_static_query_text(static_source, value.trim())?;
        if search_query.is_some() {
            return None;
        }
        let match_type = match normalized_search_lua_field(&name).as_str() {
            "regex" => WindowSearchMatchType::Regex,
            "casesensitivestring" => WindowSearchMatchType::CaseSensitive,
            "caseinsensitivestring" => WindowSearchMatchType::CaseInsensitive,
            _ => return None,
        };
        search_query = Some(WindowSearchCommandQuery::Pattern {
            pattern: value,
            match_type,
        });
    }

    search_query
}

fn normalized_search_lua_field(field: &str) -> String {
    field
        .chars()
        .filter(|character| !character.is_whitespace() && *character != '-' && *character != '_')
        .collect::<String>()
        .to_ascii_lowercase()
}

fn search_query_strip_match_type_prefix<'a>(
    pattern: &'a str,
    prefixes: &[&str],
) -> Option<&'a str> {
    prefixes.iter().find_map(|prefix| {
        let candidate = pattern.get(..prefix.len())?;
        let rest = pattern.get(prefix.len()..)?;
        candidate
            .eq_ignore_ascii_case(prefix)
            .then_some(rest)
            .and_then(|rest| rest.starts_with(char::is_whitespace).then_some(rest))
            .map(str::trim)
            .filter(|pattern| !pattern.is_empty())
    })
}

fn search_current_selection_query_matches(pattern: &str) -> bool {
    let normalized = pattern
        .chars()
        .filter(|character| !character.is_whitespace() && *character != '-' && *character != '_')
        .collect::<String>()
        .to_ascii_lowercase();
    matches!(
        normalized.as_str(),
        "currentselection"
            | "currentselectionorempty"
            | "currentselectionoremptystring"
            | "currentselectionoremptystringpattern"
    )
}

fn single_line_search_query_from_selection(text: &str) -> String {
    text.lines()
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .collect::<Vec<_>>()
        .join(" ")
}

