#[allow(clippy::struct_excessive_bools)]
struct TabBarSegmentStyle {
    foreground: Color,
    background: Color,
    underline_color: Color,
    bold: bool,
    faint: bool,
    italic: bool,
    blink: bool,
    rapid_blink: bool,
    inverse: bool,
    conceal: bool,
    strikethrough: bool,
    overline: bool,
    underline_style: UnderlineStyle,
}

const fn tab_bar_segment_style(
    foreground: Color,
    background: Color,
    bold: bool,
) -> TabBarSegmentStyle {
    TabBarSegmentStyle {
        foreground,
        background,
        underline_color: Color::Default,
        bold,
        faint: false,
        italic: false,
        blink: false,
        rapid_blink: false,
        inverse: false,
        conceal: false,
        strikethrough: false,
        overline: false,
        underline_style: UnderlineStyle::None,
    }
}

fn tab_bar_item_segment_style(
    colors: NativeTabBarItemColors,
    default_foreground: Color,
    default_background: Color,
    bold: bool,
) -> TabBarSegmentStyle {
    let mut style = tab_bar_segment_style(
        match colors.fg_color {
            Some(color) => color,
            None => default_foreground,
        },
        match colors.bg_color {
            Some(color) => color,
            None => default_background,
        },
        bold,
    );
    if let Some(intensity) = colors.intensity {
        match intensity {
            NativeFormatIntensity::Normal => {
                style.bold = false;
                style.faint = false;
            }
            NativeFormatIntensity::Bold => {
                style.bold = true;
                style.faint = false;
            }
            NativeFormatIntensity::Half => {
                style.bold = false;
                style.faint = true;
            }
        }
    }
    if let Some(underline) = colors.underline {
        style.underline_style = underline_style_for_native_format(underline);
    }
    if let Some(italic) = colors.italic {
        style.italic = italic;
    }
    if let Some(strikethrough) = colors.strikethrough {
        style.strikethrough = strikethrough;
    }
    style
}

fn tab_bar_tab_label_segments(
    position: usize,
    tab_id: rssh_core::TabId,
    pane_count: usize,
    active: bool,
    title: Option<&str>,
    progress: PaneProgress,
    options: TabBarTabLabelOptions,
) -> TabBarTabLabelSegments {
    let marker = if active { "*" } else { "" };
    let progress = pane_progress_label(progress);
    let prefix = if options.show_tab_index {
        let display_index = if options.zero_based_tab_index {
            position
        } else {
            position + 1
        };
        format!("{display_index}:{}{}", tab_id.get(), marker)
    } else {
        format!("{}{}", tab_id.get(), marker)
    };
    let suffix = if options.show_close_button {
        " x "
    } else {
        " "
    };
    match title {
        Some(title) if !progress.is_empty() => TabBarTabLabelSegments {
            prefix: format!(" {prefix} panes:{pane_count} {progress} "),
            title: title.to_owned(),
            suffix: suffix.to_owned(),
        },
        Some(title) => TabBarTabLabelSegments {
            prefix: format!(" {prefix} panes:{pane_count} "),
            title: title.to_owned(),
            suffix: suffix.to_owned(),
        },
        None if !progress.is_empty() => TabBarTabLabelSegments {
            prefix: format!(" {prefix} panes:{pane_count} "),
            title: progress,
            suffix: suffix.to_owned(),
        },
        None => TabBarTabLabelSegments {
            prefix: format!(
                " {prefix} panes:{pane_count}{}",
                if options.show_close_button {
                    " x "
                } else {
                    " "
                }
            ),
            title: String::new(),
            suffix: String::new(),
        },
    }
}

